import React, { useState } from "react";
import { Link, useLocation } from "react-router-dom";
// import "./Layout.css"; // optional for custom styles

const Layout = ({ children }) => {
  const location = useLocation();
  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);

  return (
    <div className={`app-wrapper ${sidebarCollapsed ? "collapsed" : ""}`}>
      {/* Sidebar */}
      <aside className="sidebar bg-dark text-white">
        <div className="sidebar-header p-3">
          <h4>ORA Admin</h4>
        </div>
        <ul className="list-unstyled p-2">
          <li className={location.pathname === "/" ? "active" : ""}>
            <Link to="/">Dashboard</Link>
          </li>
          <li className={location.pathname === "/users" ? "active" : ""}>
            <Link to="/users">Users</Link>
          </li>
          <li>
            <span>Departments</span>
            <ul>
              <li className={location.pathname === "/departments/hr" ? "active" : ""}>
                <Link to="/departments/hr">HR</Link>
              </li>
              <li className={location.pathname === "/departments/it" ? "active" : ""}>
                <Link to="/departments/it">IT</Link>
              </li>
            </ul>
          </li>
        </ul>
        <button
          className="btn btn-sm btn-secondary m-3"
          onClick={() => setSidebarCollapsed(!sidebarCollapsed)}
        >
          {sidebarCollapsed ? "Expand" : "Collapse"}
        </button>
      </aside>

      {/* Main content */}
      <div className="main-content">
        <nav className="navbar navbar-light bg-light p-3">
          <span className="navbar-brand mb-0 h1">ORA Admin Panel</span>
        </nav>
        <div className="content p-3">{children}</div>
      </div>
    </div>
  );
};

export default Layout;
